content.content:
  padding: 12px 0;
  box-shadow: inset 0 1px 0 0 var(--border-subtle);
}

.agent-row-line,
.agent-account {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
}

/* The account's button drops under its text in a narrow dock. */
.agent-account {
  flex-wrap: wrap;
}

.agent-account-offer {
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: 100%;
}

.agent-account-eyebrow {
  font: var(--font-label-bold);
  color: var(--text-secondary);
}

/* The first-month offer: a headline on the selected surface, boards 1a to 1c. */
.credit-offer {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 16px;
  border-radius: var(--radius-medium);
  background: var(--surface-selected);
}

.credit-offer-copy {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.credit-offer-copy p {
  margin: 0;
  font: var(--font-body-small);
  color: var(--text-primary);
}

.credit-offer-copy p.credit-offer-note {
  font: var(--font-body-small-bold);
}

h2.credit-offer-title {
  margin: 0;
  font: var(--font-section);
  color: var(--text-primary);
}

/* The sign-in every screen shares (SignInDoor.css), in a column as the
   first-launch welcome's offer card spaces it. */
.account-sign-in {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.account-sign-in .credit-offer-copy {
  margin-bottom: 8px;
}

/* What the account row says under its line: the browser it is waiting on,
   or why the last sign-in did not finish. Empty, it takes no room. */
.agent-account-detail {
  flex-basis: 100%;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.agent-account-detail:empty {
  display: none;
}

.agent-row-copy {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
}

.agent-row-name {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px;
  font: var(--font-body);
  color: var(--text-primary);
}

.agent-row-detail {
  font: var(--font-body-small);
  color: var(--text-secondary);
}

.agent-row-status {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 8px;
  font: var(--font-label);
  color: var(--text-secondary);
}

/* The glyph stays with its words in a narrow dock; only the hint drops to a
   line of its own. */
.agent-row-status-label {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.agent-row-status .jp-icon,
.agent-row-action .jp-icon {
  width: var(--setup-card-icon-size);
  height: var(--setup-card-icon-size);
}

.agent-row-status--saved .jp-icon { color: var(--status-success); }
.agent-row-status--sessionOnly { color: var(--text-primary); }
.agent-row-status--sessionOnly .jp-icon { color: var(--status-warning); }
.agent-row-status--rejected { color: var(--status-danger); }

/* A key's hint is code, and always at full contrast: it is what tells two
   keys apart. */
.agent-key-hint,
.agent-key-keeps code {
.printer-form-row .jp-icon {
  flex: 0 0 auto;
  width: var(--select-chevron-size);
  height: var(--select-chevron-size);
  color: var(--text-secondary);
}

.printer-form-online {
  flex: 0 0 auto;
  width: var(--status-dot-size);
  height: var(--status-dot-size);
  border-radius: 50%;
  background: var(--status-success);
}

/* A plate: the chosen one filled and bold, as the canvas's step 2. */
.printer-form-choice {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
.prefs-update-line {
  display: flex;
  align-items: center;
  gap: 8px;
}

.prefs-dot--success {
  background: var(--status-success);
}

.prefs-dot--warning {
  background: var(--status-warning);
}

.prefs-row-hint {
  font: var(--font-label);

