 .../JusPrin/AgentUI/src/PreferencesApp.test.tsx    | 32 +++++++++++++++++++-
 .../JusPrin/AgentUI/src/components/Preferences.tsx | 35 +++++++++++++++-------
 2 files changed, 56 insertions(+), 11 deletions(-)
+  it('says AI is unavailable when the account’s model list failed, and asks again on Try again', async () => {
+    render(<PreferencesApp getTransport={() => host.transport} />);
+    connect(host);
+    host.deliver('setup_keys', { keys: [{ provider: 'jusprin', hint: '…wxyz', rejected: false, account: 'alex@example.com' }] });
+    const catalog = (state: string) => ({
+      defaultProvider: 'jusprin',
+      providers: [{ id: 'jusprin', label: 'JusPrin', defaultModel: 'standard', state, models: [] }],
+    });
+    host.deliver('model_catalog', catalog('loading'));
+    expect(screen.getByTestId('agent-account-status')).toHaveTextContent('Signed in as alex@example.com');
+    expect(screen.queryByRole('button', { name: 'Try again' })).toBeNull();
+
+    host.deliver('model_catalog', catalog('failed'));
+    expect(screen.getByTestId('agent-account-status')).toHaveTextContent('Signed in as alex@example.com · AI unavailable');
+    expect(screen.getByText('Your account and AI setup stay intact. Your own key or AI tool still works meanwhile.'))
+      .toBeInTheDocument();
+    expect(screen.queryByRole('button', { name: 'Sign out' })).toBeNull();
+    const asked = host.ofType('refresh_account').length;
+    await userEvent.click(screen.getByRole('button', { name: 'Try again' }));
+    expect(host.ofType('refresh_account')).toHaveLength(asked + 1);
+    // Waiting on the answer, it can't be pressed again.
+    expect(screen.getByRole('button', { name: 'Try again' })).toBeDisabled();
+
+    host.deliver('model_catalog', catalog('failed'));
+    expect(screen.getByRole('button', { name: 'Try again' })).toBeEnabled();
+    host.deliver('model_catalog', catalog('ready'));
+    expect(screen.getByTestId('agent-account-status')).toHaveTextContent(/^Signed in as alex@example\.com$/);
+    expect(screen.getByRole('button', { name: 'Sign out' })).toBeInTheDocument();
+  });
+
-      expect(screen.getByText('Pay as you go')).toBeInTheDocument();
+      expect(screen.getByText('No plan')).toBeInTheDocument();
+  ModelCatalogPayload,
+  // Reads the account again, and any model list that failed.
+  refreshAccount: () => void;
+  // Each configured provider's model list; the JusPrin account's says whether
+  // its AI can be reached.
+  modelCatalog?: ModelCatalogPayload;
-// The JusPrin account row.
-function JusPrinAccount({ savedKeys, account, actions }: {
-  savedKeys: SavedKeyInfo[]; account: AccountStatusPayload; actions: PreferencesActions;
+// The JusPrin account row. Its AI is unavailable when the account's model
+// list failed without the server refusing the sign-in (a refusal shows as a
+// sign-in that has ended); Try again asks for the list again, and the row
+// waits for the next catalog the host sends.
+function JusPrinAccount({ savedKeys, account, modelCatalog, actions }: {
+  savedKeys: SavedKeyInfo[]; account: AccountStatusPayload; modelCatalog?: ModelCatalogPayload; actions: PreferencesActions;
+  const [retriedAt, setRetriedAt] = useState<ModelCatalogPayload | undefined>();
+  const models = modelCatalog?.providers.find((provider) => provider.id === 'jusprin');
+      aiUnavailable={models?.state === 'failed'} retrying={retriedAt !== undefined && retriedAt === modelCatalog}
+      onRetry={() => { setRetriedAt(modelCatalog); actions.refreshAccount(); }}
-          <span className="prefs-credits-plan-name">{account.plan?.name ?? 'Pay as you go'}</span>
+          <span className="prefs-credits-plan-name">{account.plan?.name ?? 'No plan'}</span>
-function AccountSection({ savedKeys, account, creditAccount, chatTitles, accountBox, actions, onAgent }: {
+function AccountSection({ savedKeys, account, creditAccount, chatTitles, accountBox, modelCatalog, actions, onAgent }: {
-  chatTitles: Record<string, string>; accountBox: string | null; actions: PreferencesActions; onAgent: () => void;
+  chatTitles: Record<string, string>; accountBox: string | null; modelCatalog?: ModelCatalogPayload;
+  actions: PreferencesActions; onAgent: () => void;
-      <JusPrinAccount savedKeys={savedKeys} account={account} actions={actions} />
+      <JusPrinAccount savedKeys={savedKeys} account={account} modelCatalog={modelCatalog} actions={actions} />

